<style>
  /* Import Clash Display Font */
  @import url('https://fonts.cdnfonts.com/css/clash-display');

  /* ===== SECTION WRAPPER ===== */
  .opal-roll-section {
    position: relative;
    z-index: 5;
    padding: 40px 0;
    background: transparent;
    overflow: hidden;
  }

  /* ===== TRACK (TILTED STRIP) ===== */
  .opal-roll-track {
    display: flex;
    width: max-content;

    /* animation */
    animation: scrollLeft 35s linear infinite;

    /* tilt */
    transform: rotate(-3deg);
    transform-origin: center;

    /* design - updated with blue (#073875) */
    background: #073875;
    padding: 22px 0;
  }

  /* ===== CONTENT ===== */
  .opal-roll-content {
    display: flex;
    gap: 40px;
    padding-right: 60px;
  }

  /* ===== TEXT STYLE ===== */
  .opal-roll-content span {
    font-family: 'Clash Display', sans-serif;
    font-size: 22px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #FBEAE5;
    white-space: nowrap;
    position: relative;
  }

  /* separator icon - updated with maroon (#750707) */
  .opal-roll-content span::after {
    content: "⚡";
    margin-left: 50px;
    color: #750707;
    font-size: 18px;
  }

  /* remove last separator */
  .opal-roll-content span:last-child::after {
    content: "";
  }

  /* ===== ANIMATION ===== */
  @keyframes scrollLeft {
    0% {
      transform: translateX(0);
    }
    100% {
      transform: translateX(-50%);
    }
  }

  /* ===== HOVER PAUSE ===== */
  .opal-roll-section:hover .opal-roll-track {
    animation-play-state: paused;
  }

  /* ===== RESPONSIVE ===== */
  @media (max-width: 768px) {
    .opal-roll-track {
      animation-duration: 40s;
      transform: rotate(-2deg);
      padding: 18px 0;
    }

    .opal-roll-content {
      gap: 30px;
      padding-right: 40px;
    }

    .opal-roll-content span {
      font-size: 16px;
      letter-spacing: 1px;
    }
    
    .opal-roll-content span::after {
      margin-left: 30px;
      font-size: 14px;
    }
  }

  /* Extra small screens */
  @media (max-width: 480px) {
    .opal-roll-content span {
      font-size: 12px;
    }
    
    .opal-roll-content {
      gap: 20px;
      padding-right: 25px;
    }
    
    .opal-roll-content span::after {
      margin-left: 20px;
      font-size: 10px;
    }
  }
</style>

<script>
  // Optional: dynamically adjust speed based on screen width
  const track = document.querySelector('.opal-roll-track');

  function adjustSpeed() {
    if (window.innerWidth < 768) {
      track.style.animationDuration = "25s";
    } else {
      track.style.animationDuration = "35s";
    }
  }

  if (track) {
    adjustSpeed();
    window.addEventListener('resize', adjustSpeed);
  }
</script>","_margin":{"unit":"px","top":"-60","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_mobile":{"unit":"px","top":"-120","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"e7c4e35","elType":"container","settings":{"flex_direction":"row","flex_gap":{"unit":"px","size":20,"column":"20","row":"20"},"flex_direction_tablet":"row","flex_align_items":"center","padding":{"unit":"px","top":"60","right":"10","bottom":"60","left":"10","isLinked":false}},"elements":[{"id":"1f59dce","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"50"},"sticky":"top","sticky_parent":"yes"},"elements":[{"id":"542e564","elType":"widget","settings":{"title":" <span>  Special Vehicle Towing 

