</span>","typography_typography":"custom"},"elements":[],"widgetType":"heading"},{"id":"5ef5c78","elType":"widget","settings":{"editor":"<p class="ds-markdown-paragraph">BP Towing provides winch-out services across Calgary and a 30‑km radius, including rural roads and off‑road areas. We regularly respond to:</p><p class="ds-markdown-paragraph">Downtown Calgary, Beltline, Inglewood, Bridgeland, Mission, Kensington, Hillhurst, Brentwood, Dalhousie, Varsity, Edgemont, Huntington Hills, Marlborough, Forest Lawn, Dover, Ogden, Sundance, Midnapore, Evergreen, Bridlewood, Signal Hill, Aspen Woods, Rocky Ridge, Royal Oak, Panorama Hills, Coventry Hills, and all neighbouring communities.</p><p class="ds-markdown-paragraph">We also serve major roadways including Deerfoot Trail (Highway 2), Crowchild Trail, Glenmore Trail, Stoney Trail, Macleod Trail, Sarcee Trail, Highway 1 (Trans‑Canada), Highway 8, and Highway 22X, plus rural roads, job sites, fields, and off‑road areas within 30 km of Calgary.</p>","typography_typography":"custom","typography_font_size_tablet":{"unit":"px","size":13,"sizes":[]},"paragraph_spacing":{"unit":"px","size":10,"sizes":[]}},"elements":[],"widgetType":"text-editor"},{"id":"fc92d13","elType":"widget","settings":{"text":"Call Now | (403) 991-2265","link":{"url":"tel:+14039912265","is_external":"","nofollow":"","custom_attributes":""},"__globals__":{"bg_color":"","bg_color_hover":"","border_color":"globals/colors?id=a3bc34d"},"bg_color":"#750707","bg_color_hover":"#31396F","_margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"border_radius":{"unit":"px","top":"10","right":"10","bottom":"10","left":"10","isLinked":true},"_animation_delay":100,"_mask_shape":"trapezoid-down","icon_position":"left","typography_font_size":{"unit":"px","size":18,"sizes":[]},"_padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLi