<style>
  /* Import Clash Display Font */
  @import url('https://fonts.cdnfonts.com/css/clash-display');

  /* ===== SECTION WRAPPER ===== */
  .opal-roll-section {
    position: relative;
    z-index: 5;
    padding: 40px 0;
    background: transparent;
    overflow: hidden;
  }

  /* ===== TRACK (TILTED STRIP) ===== */
  .opal-roll-track {
