  }

  /* ===== TEXT STYLE ===== */
  .opal-roll-content span {
    font-family: 'Clash Display', sans-serif;
    font-size: 22px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #FBEAE5;
    white-space: nowrap;
    position: relative;
  }

  /* separator icon - updated with maroon (#750707) */
  .opal-roll-content span::after {
    content: "⚡";
    margin-left: 50px;
    color: #750707;
    font-size: 18px;
  }

  /* remove last separator */
  .opal-roll-content span:last-child::after {
    content: "";
  }

  /* ===== ANIMATION ===== */
  @keyframes scrollLeft {
    0% {
      transform: translateX(0);
    }
    100% {
      transform: translateX(-50%);
    }
  }

  /* ===== HOVER PAUSE ===== */
  .opal-roll-section:hover .opal-roll-track {
    animation-play-state: paused;
  }

  /* ===== RESPONSIVE ===== */
  @media (max-width: 768px) {
    .opal-roll-track {
      animation-duration: 40s;
      transform: rotate(-2deg);
      padding: 18px 0;
    }

    .opal-roll-content {
      gap: 30px;
      padding-right: 40px;
    }

    .opal-roll-content span {
      font-size: 16px;
      letter-spacing: 1px;
    }
    
    .opal-roll-content span::after {
      margin-left: 30px;
      font-size: 14px;
    }
  }

  /* Extra small screens */
  @media (max-width: 480px) {
    .opal-roll-content span {
      font-size: 12px;
    }
    
    .opal-roll-content {
      gap: 20px;
      padding-right: 25px;
    }
    
    .opal-roll-content span::after {
      margin-left: 20px;
      font-size: 10px;
    }
  }
</style>

