<style>
  /* Import Clash Display Font */
  @import url('https://fonts.cdnfonts.com/css/clash-display');

  /* ===== SECTION WRAPPER ===== */
  .opal-roll-section {
    position: relative;
    z-index: 5;
    padding: 40px 0;
    background: transparent;
    overflow: hidden;
  }

  /* ===== TRACK (TILTED STRIP) ===== */
  .opal-roll-track {
    display: flex;
    width: max-content;

    /* animation */
    animation: scrollLeft 35s linear infinite;

    /* tilt */
    transform: rotate(-3deg);
    transform-origin: center;

    /* design - updated with blue (#073875) */
    background: #073875;
    padding: 22px 0;
  }

  /* ===== CONTENT ===== */
  .opal-roll-content {
    display: flex;
    gap: 40px;
    padding-right: 60px;
  }

  /* ===== TEXT STYLE ===== */
  .opal-roll-content span {
    font-family: 'Clash Display', sans-serif;
    font-size: 22px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #FBEAE5;
    white-space: nowrap;
    position: relative;
  }

  /* separator icon - updated with maroon (#750707) */
  .opal-roll-content span::after {
    content: "⚡";
    margin-left: 50px;
    color: #750707;
    font-size: 18px;
  }

  /* remove last separator */
  .opal-roll-content span:last-child::after {
    content: "";
  }

  /* ===== ANIMATION ===== */
  @keyframes scrollLeft {
    0% {
      transform: translateX(0);
    }
    100% {
      transform: translateX(-50%);
    }
  }

  /* ===== HOVER PAUSE ===== */
  .opal-roll-section:hover .opal-roll-track {
    animation-play-state: paused;
  }

  /* ===== RESPONSIVE ===== */
  @media (max-width: 768px) {
    .opal-roll-track {
      animation-duration: 40s;
      transform: rotate(-2deg);
      padding: 18px 0;
    }

    .opal-roll-content {
      gap: 30px;
      padding-right: 40px;
    }

    .opal-roll-content span {
      font-size: 16px;
      letter-spacing: 1px;
    }
    
    .opal-roll-content span::after {
      margin-left: 30px;
      font-size: 14px;
    }
  }

  /* Extra small screens */
  @media (max-width: 480px) {
    .opal-roll-content span {
      font-size: 12px;
    }
    
    .opal-roll-content {
      gap: 20px;
      padding-right: 25px;
    }
    
    .opal-roll-content span::after {
      margin-left: 20px;
      font-size: 10px;
    }
  }
</style>

<script>
  // Optional: dynamically adjust speed based on screen width
  const track = document.querySelector('.opal-roll-track');

  function adjustSpeed() {
    if (window.innerWidth < 768) {
      track.style.animationDuration = "25s";
    } else {
      track.style.animationDuration = "35s";
    }
  }

  if (track) {
    adjustSpeed();
    window.addEventListener('resize', adjustSpeed);
  }
</script>","_margin":{"unit":"px","top":"-60","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_mobile":{"unit":"px","top":"-120","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"8c488b8","elType":"container","settings":{"flex_direction":"row","flex_gap":{"unit":"px","size":20,"column":"20","row":"20"},"flex_direction_tablet":"row","flex_align_items":"center","padding":{"unit":"px","top":"60","right":"10","bottom":"60","left":"10","isLinked":false}},"elements":[{"id":"5731396","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"50"},"sticky":"top","sticky_parent":"yes"},"elements":[{"id":"acf776d","elType":"widget","settings":{"title":" <span>  Jump Start Service 
</span>Designed for Real-Life Situations","typography_typography":"custom"},"elements":[],"widgetType":"heading"},{"id":"893e9ce","elType":"widget","settings":{"editor":"<p class="ds-markdown-paragraph">Dead batteries don't give warning. One day your car starts fine. The next day – nothing. Cold Calgary winters are especially hard on batteries, but summer heat can kill them too. Whatever the reason, BP Towing doesn't ask questions – we just help.</p><p class="ds-markdown-paragraph"><strong>Common dead battery situations we handle:</strong></p><ul><li><p class="ds-markdown-paragraph"><strong>Left lights on overnight</strong> – Headlights, interior lights, or trunk lights drain the battery</p></li><li><p class="ds-markdown-paragraph"><strong>Extreme cold weather</strong> – Calgary winters below -20°C reduce battery capacity by 50% or more</p></li><li><p class="ds-markdown-paragraph"><strong>Old or failing battery</strong> – Most car batteries last 3–5 years. After that, they're unreliable</p></li><li><p class="ds-markdown-paragraph"><strong>Parasitic drain</strong> – Something electrical stays on when the car is off (radio, GPS, aftermarket accessories)</p></li><li><p class="ds-markdown-paragraph"><strong>Alternator failure</strong> – The battery isn't charging while you drive. A jump start gets you going, but you'll need a tow soon</p></li><li><p class="ds-markdown-paragraph"><strong>Infrequent driving</strong> – If you drive rarely, the battery drains naturally over time</p></li><li><p class="ds-markdown-paragraph"><strong>Door left ajar</strong> – Dome lights can drain a battery overnight</p></li></ul>","typography_typography":"custom","typography_font_size_tablet":{"unit":"px","size":13,"sizes":[]},"paragraph_spacing":{"unit":"px","size":10,"sizes":[]}},"elements":[],"widgetType":"text-editor"},{"id":"b716a42","elType":"widget","settings":{"text":"Call Now | (403) 991-2265","link":{"url":"tel:+14039912265","is_external":"","nofollow":"","custom_attributes":""},"__