    <!-- duplicate -->
    <div class="opal-roll-content">
      <span>Auto Towing</span>
      <span>Roadside Assistance</span>
      <span>Flat Tire Change or Replacement</span>
      <span>Fuel Delivery</span>
      <span>Vehicle Jump Start</span>
