    </div>

  </div>
</section>

<style>
  /* Import Clash Display Font */
  @import url('https://fonts.cdnfonts.com/css/clash-display');

  /* ===== SECTION WRAPPER ===== */
  .opal-roll-section {
    position: relative;
    z-index: 5;
    padding: 40px 0;
    background: transparent;
    overflow: hidden;
  }

  /* ===== TRACK (TILTED STRIP) ===== */
  .opal-roll-track {
    display: flex;
    width: max-content;

    /* animation */
    animation: scrollLeft 35s linear infinite;

    /* tilt */
    transform: rotate(-3deg);
    transform-origin: center;

    /* design - updated with blue (#073875) */
    background: #073875;
    padding: 22px 0;
  }

  /* ===== CONTENT ===== */
  .opal-roll-content {
    display: flex;
    gap: 40px;
    padding-right: 60px;
  }

  /* ===== TEXT STYLE ===== */
  .opal-roll-content span {
    font-family: 'Clash Display', sans-serif;
    font-size: 22px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: #FBEAE5;
    white-space: nowrap;
    position: relative;
  }

  /* separator icon - updated with maroon (#750707) */
  .opal-roll-content span::after {
    content: "⚡";
    margin-left: 50px;
    color: #750707;
    font-size: 18px;
  }

  /* remove last separator */
  .opal-roll-content span:last-child::after {
    content: "";
  }

  /* ===== ANIMATION ===== */
  @keyframes scrollLeft {
    0% {
      transform: translateX(0);
    }
    100% {
      transform: translateX(-50%);
    }
  }

  /* ===== HOVER PAUSE ===== */
  .opal-roll-section:hover .opal-roll-track {
    animation-play-state: paused;
  }

  /* ===== RESPONSIVE ===== */
  @media (max-width: 768px) {
    .opal-roll-track {
      animation-duration: 40s;
      transform: rotate(-2deg);
      padding: 18px 0;
    }

    .opal-roll-content {
      gap: 30px;
      padding-right: 40px;
    }

    .opal-roll-content span {
      font-size: 16px;
      letter-spacing: 1px;
    }
    
    .opal-roll-content span::after {
      margin-left: 30px;
      font-size: 14px;
    }
  }

  /* Extra small screens */
  @media (max-width: 480px) {
    .opal-roll-content span {
      font-size: 12px;
    }
    
    .opal-roll-content {
      gap: 20px;
      padding-right: 25px;
    }
    
    .opal-roll-content span::after {
      margin-left: 20px;
      font-size: 10px;
    }
  }
</style>

<script>
  // Optional: dynamically adjust speed based on screen width
  const track = document.querySelector('.opal-roll-track');

  function adjustSpeed() {
    if (window.innerWidth < 768) {
      track.style.animationDuration = "25s";
    } else {
      track.style.animationDuration = "35s";
    }
  }

  if (track) {
    adjustSpeed();
    window.addEventListener('resize', adjustSpeed);
  }
</script>","_margin":{"unit":"px","top":"-60","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_mobile":{"unit":"px","top":"-120","right":"0","bottom":"0","left":"0","isLinked":false}},"elements":[],"widgetType":"html"}],"isInner":false},{"id":"b3ed276","elType":"container","settings":{"flex_direction":"column","background_background":"classic","background_color":"#EFEFEF","margin":{"unit":"px","top":"56","right":"0","bottom":"0","left":"0","isLinked":false},"padding":{"unit":"px","top":"50","right":"15","bottom":"36","left":"15","isLinked":false},"margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"__globals__":{"background_color":""}},"elements":[{"id":"1298a72","elType":"widget","settings":{"title":"Complete Towing Calgary Services - <span>Roadside Assistance & Recovery</span>","subtitle":"WHAT WE OFFER","align":"center","title_color":"#000000","title_typography_typography":"custom","title_typography_font_size":{"unit":"px","size":40,"sizes":[]},"title_typography_font_size_mobile":{"unit":"px","size":30,"sizes":[]},"__globals__":{"title_color":"","accent_color":""},"accent_color":"#C81E1E"},"elements":[],"widgetType":"pt-heading"},{"id":"58b8602","elType":"widget","settings":{"editor":"<p>From simple roadside calls to full vehicle recovery BP Towing Calgary handles it all.</p>","typography_typography":"custom","typography_font_size_tablet":{"unit":"px","size":13,"sizes":[]},"align":"center"},"elements":[],"widgetType":"text-editor"},{"id":"75f39da","elType":"container","settings":{"container_type":"grid","presetTitle":"Grid","presetIcon":"eicon-container-grid","content_width":"full","grid_gaps":{"column":"10","row":"10","isLinked":true,"unit":"px"}},"elements":[{"id":"29f82cc","elType":"widget","settings":{"image":{"url":"https://bptowingservice.ca/wp-content/uploads/2026/06/WhatsApp-Image-2026-05-28-at-10.43.34-PM.jpeg","id":4166,"size":"","alt":"","source":"library"},"thumbnail_size":"custom","thumbnail_cust